<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('gallery');$base='/admin/gallery.php';
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$a=cmsStr($_POST['action']??'save',20);$id=cmsInt($_POST['id']??0);if($a==='delete'&&$id){$s=$pdo->prepare('SELECT image_path FROM gallery_items WHERE id=:id');$s->execute([':id'=>$id]);$old=$s->fetchColumn();$pdo->prepare('DELETE FROM gallery_items WHERE id=:id')->execute([':id'=>$id]);if(is_string($old))cmsDeleteLocalUpload($old);cmsAudit('gallery.delete','gallery_items',(string)$id);cmsAdminRedirect($base,'تم الحذف.');}if($a==='toggle'&&$id){$pdo->prepare('UPDATE gallery_items SET is_active=1-is_active WHERE id=:id')->execute([':id'=>$id]);cmsAudit('gallery.toggle','gallery_items',(string)$id);cmsAdminRedirect($base,'تم تحديث الحالة.');}
$ar=cmsStr($_POST['title_ar']??'',255);$en=cmsStr($_POST['title_en']??'',255);$sort=cmsInt($_POST['sort_order']??0);$active=cmsBool($_POST['is_active']??0);$img=cmsUploadFile('image','gallery',['jpg','jpeg','png','webp','gif'],8*1024*1024);if($id){$s=$pdo->prepare('SELECT image_path FROM gallery_items WHERE id=:id');$s->execute([':id'=>$id]);$old=(string)($s->fetchColumn()?:'');$path=$img??$old;if($path==='')cmsAdminRedirect($base,'الصورة مطلوبة.');$q=$pdo->prepare('UPDATE gallery_items SET title_ar=:ar,title_en=:en,image_path=:p,sort_order=:s,is_active=:i WHERE id=:id');$q->execute([':ar'=>$ar?:null,':en'=>$en?:null,':p'=>$path,':s'=>$sort,':i'=>$active,':id'=>$id]);if($img&&$old&&$old!==$img)cmsDeleteLocalUpload($old);$act='gallery.update';}else{if(!$img)cmsAdminRedirect($base,'الصورة مطلوبة.');$q=$pdo->prepare('INSERT INTO gallery_items(title_ar,title_en,image_path,sort_order,is_active) VALUES(:ar,:en,:p,:s,:i)');$q->execute([':ar'=>$ar?:null,':en'=>$en?:null,':p'=>$img,':s'=>$sort,':i'=>$active]);$act='gallery.create';}cmsAudit($act,'gallery_items',(string)$id);cmsAdminRedirect($base,'تم الحفظ.');}
$edit=null;if($id=cmsInt($_GET['edit']??0)){$s=$pdo->prepare('SELECT * FROM gallery_items WHERE id=:id');$s->execute([':id'=>$id]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT * FROM gallery_items ORDER BY sort_order,id')->fetchAll();cmsAdminHead('المعرض');cmsAdminSidebar('gallery');cmsAdminTopbar('المعرض');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><div class="split"><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>صورة</th><th>العنوان</th><th>الحالة</th><th>ترتيب</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><img class="thumb" src="<?=cmsE($r['image_path'])?>" alt=""></td><td><?=cmsE((string)$r['title_ar'])?><div class="muted"><?=cmsE((string)$r['title_en'])?></div></td><td><span class="pill <?=$r['is_active']?'ok':'bad'?>"><?=$r['is_active']?'ظاهر':'مخفي'?></span></td><td><?=$r['sort_order']?></td><td><div class="actions"><a class="btn" href="?edit=<?=$r['id']?>">تعديل</a><form method="post"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="toggle">إظهار/إخفاء</button><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف؟')">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2><?=$edit?'تعديل':'إضافة صورة'?></h2><form method="post" enctype="multipart/form-data"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="field"><span>عنوان AR</span><input name="title_ar" value="<?=cmsE((string)($edit['title_ar']??''))?>"></label><label class="field"><span>Title EN</span><input name="title_en" value="<?=cmsE((string)($edit['title_en']??''))?>"></label><label class="field"><span>الصورة</span><input type="file" name="image" accept="image/*" <?=$edit?'':'required'?>></label><div class="form-grid"><label class="field"><span>الترتيب</span><input type="number" name="sort_order" value="<?=intval($edit['sort_order']??0)?>"></label><label class="module-row"><span>ظاهر</span><input class="check" type="checkbox" name="is_active" value="1" <?=cmsChecked($edit['is_active']??1)?>></label></div><div class="actions" style="margin-top:16px"><button class="btn primary">حفظ</button><?php if($edit):?><a class="btn" href="<?=$base?>">إلغاء</a><?php endif;?></div></form></section></div></div><?php cmsAdminEnd();
